values
  ('716286dd-05b1-4f87-8b3b-a0c559bcafc4', 'Shoulder width three-point push-up', 'Chest', 'Get into a push-up position with your shoulders directly above your hands and your feet hip-width apart. Draw your belly button in towards your spine and tighten your abdominal muscles. Lift your left foot about five centimetres off the floor. Point your toes straight down. Do not move your hips. Your body forms a straight line from your head to your heels throughout the exercise. Now bend your elbows, lower your chest to the floor and push yourself back up. Repeat the exercise on the other side.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'lxmx', 'https://wger.de/en/exercise/1209/view/'),
  ('7e039ac7-37ab-49f9-9ae8-c7efeef070cd', 'Shoulder Y-pull cable', null, 'on a cable rack cross the cables and pull elbows to ceiling close to the body.', 'Cable machine', 'wger', 'CC-BY-SA 4', null, 'https://wger.de/en/exercise/1755/view/'),
  ('43eeec70-df51-4cad-9bef-a35261b0caaf', 'Shrimp Squat', 'Glutes, Quads', 'Single leg squat where one leg is behind you.', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'Happy', 'https://wger.de/en/exercise/1739/view/'),
  ('6199b3c7-3ccb-47fa-89bb-ef7fef12c0e3', 'Shrugs on Multipress', 'Shoulders', null, null, 'wger', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/575/view/'),
  ('270e108d-3cd2-45a9-807b-c357317eb15c', 'Shrugs, Barbells', 'Shoulders', 'Take a barbell and stand with a straight body, the arms are hanging freely in front of you. Lift from this position the shoulders as high as you can, but don''t bend the arms during the movement. On the highest point, make a short pause of 1 or 2 seconds before returning slowly to the initial position.
When training with a higher weight, make sure that you still do the whole movement!', 'Barbell', 'wger', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/571/view/'),
  ('72a945ec-3a7f-424b-9a05-1616ef7dce91', 'Shrugs, Dumbbells', 'Shoulders', 'Stand with straight body, the hands are hanging freely on the side and hold each a dumbbell. Lift from this position the shoulders as high as you can, but don''t bend the arms during the movement. On the highest point, make a short pause of 1 or 2 seconds before returning slowly to the initial position.
When training with a higher weight, make sure that you still do the whole movement!', 'Dumbbell', 'wger', 'CC-BY-SA 3', 'wger.de', 'https://wger.de/en/exercise/572/view/'),
  ('d36fdd3c-9a35-4643-a3fd-57db78c866d6', 'Side bend', 'Obliquus externus abdominis', 'With a weight in one hand, extend that arm down and bend the other arm, resting your hand on your head. Now move the hand holding the weight by rotating your torso up and down.', 'Dumbbell', 'wger', 'CC-BY-SA 4', null, 'https://wger.de/en/exercise/1188/view/'),
  ('919bb48a-42fe-4a11-9078-ea2b5087c49f', 'Side Bends on Machine', 'Obliquus externus abdominis', null, 'Dumbbell', 'wger', 'CC-BY-SA 3', 'klabautermann', 'https://wger.de/en/exercise/556/view/'),
  ('2f8ee51b-f493-47f7-8b2a-1da16c128f73', 'Side Crunch', 'Obliquus externus abdominis', 'Hold weight in one hand. Bend side ways to the knee. Pull upo to upright position using your obliquus.', 'Gym mat', 'wger', 'CC-BY-SA 3', 'kwrindy', 'https://wger.de/en/exercise/576/view/'),
  ('cf1f0fed-6310-4210-8f7d-22e375e6c60c', 'Side Dumbbell Trunk Flexion', 'Obliquus externus abdominis', 'AKA dumbbell side bends. Stand in line with the hips with slightly bent knees, maintain the natural curvature of the spine, hand stretched by the body, grip the barbell with one hand. Make slow and controlled torso side flexions till you reach the angle of approximately 45°.', 'Dumbbell', 'wger', 'CC-BY-SA 3', 'GiglioRosso', 'https://wger.de/en/exercise/577/view/'),
  ('dba57084-d148-4b22-bb90-2fdd3a845ca4', 'Side Lateral Raise (Cable)', 'Lats', 'Lift with your elbows leading, not your hands.
Don’t shrug your shoulders; keep traps quiet.', 'Cable machine', 'wger', 'CC-BY-SA 4', 'barry', 'https://wger.de/en/exercise/1730/view/'),
  ('065ff3ca-a9e8-4339-997e-d65556d9ebf3', 'Side lateral raise - Back (Cable)', 'Shoulders', 'on a cable rack do a side lateral raise with the cable behind you. focus on tension in the front of the shoulder.', 'Cable machine', 'wger', 'CC-BY-SA 4', null, 'https://wger.de/en/exercise/1753/view/'),
  ('7f9c13ab-1718-4f8a-8636-232f05f5f640', 'Side lateral raise - Front (Cable)', 'Shoulders', 'in a cablerack do a side lateral raise with cable in front of you, with focus in tension on the back of your shoulder.', 'Cable machine', 'wger', 'CC-BY-SA 4', null, 'https://wger.de/en/exercise/1752/view/'),
  ('7212cc74-656e-47ce-8292-d211676f2ee1', 'Side Lying Hip Abduction', null, '- Begin by lying down on your side with your top leg straight and your bottom leg bent for support.
