  ('0dd4dde7-9712-4c06-8ebe-16bc7a0b1917', 'Side Straight-Arm Pulldown (Cable)', 'Lats', 'Keep your torso still, pulling the handle down along your side using the outer lat.
Don’t twist your body or rotate your torso to cheat the rep.', 'Cable machine', 'wger', 'CC-BY-SA 4', 'barry', 'https://wger.de/en/exercise/1727/view/'),
  ('e3f424e1-4c9f-4892-8df2-230624680439', 'Side stretch', null, 'View the video to undestand the exercise', 'none (bodyweight exercise)', 'wger', 'CC-BY-SA 4', 'Davidgj32', 'https://wger.de/en/exercise/1861/view/'),
  ('9374fdaf-411f-4ae6-8f0c-21cc2d3dc667', 'Side to Side Push Ups', 'Shoulders, Obliquus externus abdominis, Chest, Triceps', '-start in push up position
